DO $seed$
DECLARE r record; v record; category_id bigint; brand_id bigint; product_id bigint; variant_id bigint;
BEGIN
 FOR r IN SELECT * FROM "Cps41Products" LOOP
  SELECT "MaPhanLoai" INTO category_id FROM "PhanLoai" WHERE "DuongDan"=r.category;
  SELECT "MaThuongHieu" INTO brand_id FROM "ThuongHieu" WHERE "DuongDan"=r.brand;
  IF category_id IS NULL OR brand_id IS NULL THEN RAISE EXCEPTION 'Missing category or brand for %',r.slug; END IF;
  product_id:=NULL;
  INSERT INTO "SanPham" ("MaPhanLoai","MaThuongHieu","TenSanPham","DuongDan","TenTimKiem","MoTaNgan","MoTaChiTiet","SoThangBaoHanh","ThongSoChung","DuongDanNguon","NgayThuThap","LaDuLieuMau","DangHienThi","NgayCapNhat")
  VALUES (category_id,brand_id,r.name,r.slug,lower(r.name),'Thông tin và giá tham khảo; tồn kho là dữ liệu thử nghiệm.','Ảnh, màu sắc và giá tham khảo từ CellphoneS tại thời điểm thu thập; tồn kho dùng để thử nghiệm.',0,'{}'::jsonb,r.source,DATE '2026-11-16',true,true,now()) ON CONFLICT ("DuongDan") DO NOTHING RETURNING "MaSanPham" INTO product_id;
  IF product_id IS NULL THEN CONTINUE; END IF;
  FOR v IN SELECT * FROM "Cps41Variants" WHERE slug=r.slug LOOP
   INSERT INTO "BienTheSanPham" ("MaSanPham","MaHang","TenBienThe","MauSac","BoXuLy","BoXuLyDoHoa","DungLuongRam","DungLuongLuuTru","KichThuocManHinh","HeDieuHanh","ThongSoBoSung","GiaNiemYet","GiaBan","GiaVon","DangKinhDoanh","NgayCapNhat") VALUES (product_id,v.sku,v.name,v.color,r.cpu,r.gpu,r.ram,r.storage,r.screen,r.os,'{}'::jsonb,v.price,v.price,0,true,now()) RETURNING "MaBienThe" INTO variant_id;
   INSERT INTO "TonKho" ("MaKhoHang","MaBienThe","SoLuongTon","SoLuongGiu","NgayCapNhat") VALUES (1,variant_id,10,0,now());
   INSERT INTO "TepSanPham" ("MaSanPham","MaBienThe","LoaiTep","DuongDanTep","MoTaThayThe","ThuTu","DuongDanNguon","ThongTinSuDung","NgayCapNhat") VALUES (product_id,variant_id,'ANH','/media/verified-cps/'||v.image,r.name||' - '||v.color,0,v.source,'Ảnh tham khảo từ CellphoneS',now());
  END LOOP;
 END LOOP;
END $seed$;
INSERT INTO "ThuocTinhDanhMuc" ("MaPhanLoai","KyHieu","TenThuocTinh","KieuDuLieu","ThuTu")
SELECT DISTINCT p."MaPhanLoai",a.code,a.label,'CHU',500 FROM "Cps41Attrs" a JOIN "PhanLoai" p ON p."DuongDan"=a.category ON CONFLICT ("MaPhanLoai","KyHieu") DO NOTHING;
INSERT INTO "GiaTriThuocTinhBienThe" ("MaBienThe","MaSanPham","MaPhanLoai","MaThuocTinh","KieuDuLieu","GiaTriChu")
SELECT b."MaBienThe",s."MaSanPham",s."MaPhanLoai",t."MaThuocTinh",'CHU',a.value FROM "Cps41Attrs" a JOIN "SanPham" s ON s."DuongDan"=a.slug JOIN "BienTheSanPham" b ON b."MaSanPham"=s."MaSanPham" AND b."MaHang" LIKE 'CPS41-%' JOIN "ThuocTinhDanhMuc" t ON t."MaPhanLoai"=s."MaPhanLoai" AND t."KyHieu"=a.code AND t."KieuDuLieu"='CHU' ON CONFLICT ("MaBienThe","MaThuocTinh") DO NOTHING;
